// ═══ STRIPED LOCK IMPLEMENTATION ═══
class StripedLock {
    private final ReentrantLock[] locks;
    private final int mask;  // stripes - 1 (for bitwise AND)

    StripedLock(int stripes) {
        // stripes MUST be power of 2!
        stripes = Integer.highestOneBit(stripes - 1) << 1;
        locks = new ReentrantLock[stripes];
        for (int i = 0; i < stripes; i++) {
            locks[i] = new ReentrantLock();  // UNFAIR! (default)
        }
        mask = stripes - 1;
    }

    ReentrantLock getLock(Object key) {
        int hash = spread(key.hashCode());
        return locks[hash & mask];  // bitwise AND = fast modulo!
    }

    // Spread hash bits (like ConcurrentHashMap):
    private static int spread(int h) {
        return h ^ (h >>> 16);
    }
}

// ═══ USAGE: per-account operations ═══
StripedLock stripedLock = new StripedLock(16);  // 16 stripes!

void debit(String accountId, BigDecimal amount) {
    ReentrantLock lock = stripedLock.getLock(accountId);
    lock.lock();
    try {
        // Only accounts in THIS stripe are locked!
        // Other stripes: fully parallel!
        Account account = accountMap.get(accountId);
        account.debit(amount);
        auditLog.record(accountId, amount);  // multi-structure!
    } finally { lock.unlock(); }
}
// 16 stripes → ~16× less contention than 1 global lock!

// ═══ WHY UNFAIR LOCKS? ═══
// Fair: FIFO queue → every lock/unlock → context switch → ~30% slower!
// Unfair: barging allowed → thread may acquire without queuing → faster!
// Trade-off: unfair may starve individual threads (rare in practice)
// Production: UNFAIR (default) for throughput! Fair only if starvation matters.

// ═══ WHEN STRIPING > ConcurrentHashMap ═══
// 1. Multi-structure atomic: lock protects BOTH accountMap AND auditLog!
//    CHM.computeIfAbsent only locks within ONE map!
// 2. Cache stampede dedup: 100 threads miss same key → only ONE loads!
StripedLock cacheLock = new StripedLock(64);
Value getCached(String key) {
    Value cached = cache.get(key);
    if (cached != null) return cached;

    ReentrantLock lock = cacheLock.getLock(key);
    lock.lock();  // all threads for SAME key: same stripe → only 1 enters!
    try {
        cached = cache.get(key);  // double-check!
        if (cached != null) return cached;
        Value loaded = loadFromDB(key);  // ONLY ONE thread loads!
        cache.put(key, loaded);
        return loaded;
    } finally { lock.unlock(); }
}
// Without striping: 100 threads → 100 DB queries for same key!
// With striping: 1 DB query, 99 wait and use cached result!
