package com.bank.striped;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.concurrent.locks.*;
import static org.assertj.core.api.Assertions.*;

class StripedLockTest {

    static class StripedLock {
        private final ReentrantLock[] locks;
        private final int mask;
        StripedLock(int stripes) {
            stripes = Integer.highestOneBit(Math.max(stripes, 1) - 1) << 1;
            if (stripes < 1) stripes = 1;
            locks = new ReentrantLock[stripes];
            for (int i = 0; i < stripes; i++) locks[i] = new ReentrantLock();
            mask = stripes - 1;
        }
        ReentrantLock get(Object key) {
            return locks[(key.hashCode() ^ (key.hashCode() >>> 16)) & mask];
        }
    }

    // ═══ Striped lock: different keys → parallel ═══
    @Test
    void stripedLock_differentKeys_parallel() throws InterruptedException {
        StripedLock striped = new StripedLock(16);
        AtomicInteger concurrent = new AtomicInteger(0);
        AtomicInteger maxConcurrent = new AtomicInteger(0);
        int threads = 50;
        CountDownLatch done = new CountDownLatch(threads);

        for (int t = 0; t < threads; t++) {
            final String key = "ACC-" + t;  // different keys → different stripes!
            new Thread(() -> {
                ReentrantLock lock = striped.get(key);
                lock.lock();
                try {
                    int c = concurrent.incrementAndGet();
                    maxConcurrent.updateAndGet(m -> Math.max(m, c));
                    try { Thread.sleep(50); } catch (InterruptedException e) {}
                    concurrent.decrementAndGet();
                } finally { lock.unlock(); done.countDown(); }
            }).start();
        }
        done.await();

        System.out.println("Max concurrent: " + maxConcurrent.get());
        assertThat(maxConcurrent.get()).isGreaterThan(1);  // PARALLEL!
    }

    // ═══ Same key → same stripe → serialized ═══
    @Test
    void sameKey_sameStripe_serialized() throws InterruptedException {
        StripedLock striped = new StripedLock(16);
        String sameKey = "SAV2001";  // all use same key → same stripe!
        AtomicInteger maxConcurrent = new AtomicInteger(0);
        AtomicInteger concurrent = new AtomicInteger(0);
        CountDownLatch done = new CountDownLatch(5);

        for (int t = 0; t < 5; t++) {
            new Thread(() -> {
                ReentrantLock lock = striped.get(sameKey);
                lock.lock();
                try {
                    int c = concurrent.incrementAndGet();
                    maxConcurrent.updateAndGet(m -> Math.max(m, c));
                    try { Thread.sleep(50); } catch (InterruptedException e) {}
                    concurrent.decrementAndGet();
                } finally { lock.unlock(); done.countDown(); }
            }).start();
        }
        done.await();

        assertThat(maxConcurrent.get()).isEqualTo(1);  // serialized! Same stripe!
    }

    // ═══ Cache stampede prevention ═══
    @Test
    void cacheStampede_onlyOneLoads() throws InterruptedException {
        StripedLock striped = new StripedLock(16);
        ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
        AtomicInteger dbLoads = new AtomicInteger(0);
        int threads = 50;
        CountDownLatch done = new CountDownLatch(threads);

        for (int t = 0; t < threads; t++) {
            new Thread(() -> {
                String key = "SAV2001";  // ALL request same key!
                String cached = cache.get(key);
                if (cached == null) {
                    ReentrantLock lock = striped.get(key);
                    lock.lock();
                    try {
                        cached = cache.get(key);  // double-check!
                        if (cached == null) {
                            dbLoads.incrementAndGet();  // only 1 thread loads!
                            try { Thread.sleep(100); } catch (InterruptedException e) {}
                            cache.put(key, "BALANCE:100000");
                        }
                    } finally { lock.unlock(); }
                }
                done.countDown();
            }).start();
        }
        done.await();

        assertThat(dbLoads.get()).isEqualTo(1);  // ONLY 1 DB load! 49 waited!
    }
}
